def O(id,title,city,state,lat,lon,category,severity,summary,action,source,url,detail=''):
 items.append(dict(id=id,title=title,place=city,state=state,lat=lat,lon=lon,category=category,severity=severity,summary=summary,action=action,source=source,url=url,detail=detail,status='official',kind='Documented restriction / official guidance'))
