# Add visual coordinates (precomputed for offline browser use)
for item in items:
 mapper=geo.alaska if item['state']=='AK' else geo.hawaii if item['state']=='HI' else geo.mainland
 item['x'],item['y']=mapper(item['lon'],item['lat'])
assert len({i['id'] for i in items})==len(items)
assert all(i['url'] for i in items if i['status']=='official')
(root/'assets/data/hazards.json').write_text(json.dumps(items,indent=2,ensure_ascii=False))
(root/'assets/js/hazards.js').write_text('window.ATLAS_HAZARDS='+json.dumps(items,separators=(',',':'),ensure_ascii=False)+';\n')
print('hazards',len(items),'official',sum(i['status']=='official' for i in items),'planning',sum(i['status']=='illustrative' for i in items))
